<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #000000;
  --bg-elevated: #0a0a0a;
  --bg-card: #141414;
  --bg-card-hover: #1a1a1a;
  --accent: #E50914;
  --accent-hover: #f6121d;
  --accent-glow: rgba(229, 9, 20, 0.3);
  --text-primary: #FFFFFF;
  --text-secondary: rgba(255,255,255,0.7);
  --text-tertiary: rgba(255,255,255,0.5);
  --border: rgba(255,255,255,0.12);
  --border-light: rgba(255,255,255,0.08);
  --input-bg: rgba(255,255,255,0.06);
  --input-bg-focus: rgba(255,255,255,0.1);
  --overlay-gradient: linear-gradient(180deg, rgba(0,0,0,0.95) 0%, rgba(0,0,0,0.6) 50%, rgba(0,0,0,0.97) 100%);
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);
}

html { font-size: 16px; scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

img { max-width: 100%; display: block; }

/* ── Focus ── */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

/* ── Container ── */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Header ── */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  padding: 16px 0;
  transition: background var(--transition-base);
}
.header.scrolled {
  background: rgba(0,0,0,0.95);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}
.header-left { display: flex; align-items: center; gap: 32px; }
.logo {
  font-size: 1.65rem;
  font-weight: 800;
  color: var(--accent);
  letter-spacing: -0.02em;
  text-decoration: none;
  transition: opacity var(--transition-fast);
}
.logo:hover { opacity: 0.85; }
.lang-select {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(255,255,255,0.06);
  border: 1px solid var(--border);
  color: var(--text-primary);
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  font-family: inherit;
  cursor: pointer;
  transition: all var(--transition-fast);
  -webkit-appearance: none;
  appearance: none;
}
.lang-select:hover { background: rgba(255,255,255,0.1); }
.lang-select:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.header-actions { display: flex; align-items: center; gap: 12px; }
.btn-signin {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 8px 20px;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: all var(--transition-fast);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
}
.btn-signin:hover { background: var(--accent-hover); transform: translateY(-1px); box-shadow: 0 4px 16px var(--accent-glow); }

/* ── Hero ── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 120px 24px 80px;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 20% 50%, rgba(229,9,20,0.15) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 20%, rgba(180,30,200,0.1) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 80%, rgba(0,80,200,0.1) 0%, transparent 50%),
    var(--overlay-gradient),
    repeating-linear-gradient(
      45deg,
      transparent,
      transparent 2px,
      rgba(255,255,255,0.008) 2px,
      rgba(255,255,255,0.008) 4px
    );
  z-index: 0;
}
.hero-poster-1, .hero-poster-2, .hero-poster-3, .hero-poster-4, .hero-poster-5, .hero-poster-6 {
  position: absolute;
  border-radius: var(--radius-md);
  opacity: 0.08;
  transform: rotate(var(--rot, 0deg));
  background: linear-gradient(135deg, var(--accent), #6b21a8, #2563eb);
  filter: blur(1px);
  z-index: 0;
}
.hero-poster-1 { width: 160px; height: 220px; top: 15%; left: 8%; --rot: -8deg; }
.hero-poster-2 { width: 140px; height: 200px; top: 25%; right: 10%; --rot: 6deg; background: linear-gradient(135deg, #2563eb, #7c3aed); }
.hero-poster-3 { width: 120px; height: 180px; bottom: 20%; left: 15%; --rot: 3deg; background: linear-gradient(135deg, #dc2626, #ea580c); }
.hero-poster-4 { width: 150px; height: 210px; top: 10%; left: 45%; --rot: -5deg; background: linear-gradient(135deg, #7c3aed, #db2777); }
.hero-poster-5 { width: 130px; height: 190px; bottom: 15%; right: 20%; --rot: -3deg; background: linear-gradient(135deg, #0891b2, #2563eb); }
.hero-poster-6 { width: 110px; height: 170px; top: 55%; right: 35%; --rot: 7deg; background: linear-gradient(135deg, #ea580c, #dc2626); }
.hero-content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 720px;
}
.hero-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: 16px;
}
.hero-subtitle {
  font-size: clamp(1.1rem, 2.5vw, 1.4rem);
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: 24px;
}
.hero-prompt {
  font-size: clamp(0.95rem, 2vw, 1.1rem);
  color: var(--text-secondary);
  margin-bottom: 20px;
}
.hero-form {
  display: flex;
  gap: 8px;
  max-width: 540px;
  margin: 0 auto;
}
.hero-input {
  flex: 1;
  background: var(--input-bg);
  border: 1px solid var(--border);
  color: var(--text-primary);
  padding: 16px 20px;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-family: inherit;
  transition: all var(--transition-fast);
  min-width: 0;
}
.hero-input::placeholder { color: var(--text-tertiary); }
.hero-input:focus {
  outline: none;
  border-color: var(--accent);
  background: var(--input-bg-focus);
  box-shadow: 0 0 0 3px var(--accent-glow);
}
.btn-get-started {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 16px 32px;
  border-radius: var(--radius-sm);
  font-size: 1.1rem;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--transition-fast);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.btn-get-started:hover { background: var(--accent-hover); transform: translateY(-2px); box-shadow: 0 8px 24px var(--accent-glow); }
.btn-get-started:active { transform: translateY(0); }
.hero-divider {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 120px;
  background: linear-gradient(180deg, transparent 0%, var(--bg) 100%);
  z-index: 1;
  pointer-events: none;
}

/* ── Sections ── */
.section { padding: 80px 0; }
.section-heading {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 800;
  margin-bottom: 40px;
  letter-spacing: -0.01em;
}

/* ── Trending Carousel ── */
.trending-wrapper { position: relative; }
.trending-scroll {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding-bottom: 16px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.trending-scroll::-webkit-scrollbar { display: none; }
.trending-card {
  flex: 0 0 auto;
  width: 200px;
  scroll-snap-align: start;
  position: relative;
  cursor: pointer;
  transition: transform var(--transition-base);
}
.trending-card:hover { transform: translateY(-6px); }
.trending-rank {
  position: absolute;
  left: -8px;
  bottom: -8px;
  font-size: 6rem;
  font-weight: 900;
  line-height: 0.75;
  color: rgba(0,0,0,0.85);
  -webkit-text-stroke: 2px rgba(255,255,255,0.3);
  z-index: 2;
  pointer-events: none;
  user-select: none;
}
.trending-poster {
  width: 200px;
  height: 280px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--bg-card), #1a1a2e);
  overflow: hidden;
  position: relative;
}
.trending-poster-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.trending-poster-art {
  position: absolute;
  inset: 0;
  opacity: 0.6;
}
.trending-poster-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.8) 100%);
}
.trending-title {
  position: absolute;
  bottom: 12px;
  left: 12px;
  right: 12px;
  font-size: 0.9rem;
  font-weight: 600;
  z-index: 1;
  text-shadow: 0 2px 8px rgba(0,0,0,0.8);
}
.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(20,20,20,0.9);
  border: 1px solid var(--border);
  color: var(--text-primary);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 5;
  font-size: 1.3rem;
  transition: all var(--transition-fast);
  backdrop-filter: blur(8px);
}
.carousel-arrow:hover { background: rgba(40,40,40,0.95); border-color: rgba(255,255,255,0.3); }
.carousel-arrow:disabled { opacity: 0.3; cursor: default; }
.carousel-arrow-left { left: -8px; }
.carousel-arrow-right { right: -8px; }

/* ── Features ── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.feature-card {
  background: linear-gradient(135deg, #0f0f1a 0%, #14142a 100%);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 28px 24px 60px;
  position: relative;
  transition: all var(--transition-base);
  overflow: hidden;
}
.feature-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
}
.feature-card:hover {
  border-color: var(--border);
  background: linear-gradient(135deg, #12121f 0%, #181833 100%);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.feature-card-title {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 12px;
  letter-spacing: -0.01em;
}
.feature-card-desc {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.6;
}
.feature-card-icon {
  position: absolute;
  bottom: 20px;
  right: 20px;
  width: 48px;
  height: 48px;
  opacity: 0.3;
}
.feature-card-icon svg { width: 100%; height: 100%; }

/* ── FAQ ── */
.faq-list {
  max-width: 960px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  background: var(--bg-card);
  border: none;
  color: var(--text-primary);
  padding: 24px 4px;
  font-size: 1.1rem;
  font-weight: 500;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: all var(--transition-base);
  gap: 16px;
}
.faq-question:hover { background: var(--bg-card-hover); }
.faq-question-text { flex: 1; }
.faq-icon {
  flex: 0 0 auto;
  width: 36px;
  height: 36px;
  position: relative;
  transition: transform var(--transition-base);
}
.faq-icon::before,
.faq-icon::after {
  content: '';
  position: absolute;
  background: var(--text-primary);
  transition: all var(--transition-base);
}
.faq-icon::before { width: 20px; height: 2px; top: 50%; left: 50%; transform: translate(-50%, -50%); }
.faq-icon::after { width: 2px; height: 20px; top: 50%; left: 50%; transform: translate(-50%, -50%); }
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1), padding 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  background: var(--bg-card);
}
.faq-item.open .faq-answer {
  max-height: 400px;
  padding: 0 4px 24px;
}
.faq-answer p {
  font-size: 1rem;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ── CTA Section ── */
.cta-section {
  text-align: center;
  padding: 60px 0 80px;
  position: relative;
}
.cta-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 80%;
  max-width: 800px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--border), transparent);
}
.cta-form { margin-top: 24px; }
.cta-form .hero-form { margin: 0 auto; }
.cta-prompt {
  font-size: 1rem;
  color: var(--text-secondary);
  margin-bottom: 18px;
}

/* ── Footer ── */
.footer {
  padding: 60px 0 40px;
  border-top: 1px solid var(--border);
}
.footer-contact {
  color: var(--text-tertiary);
  font-size: 0.9rem;
  margin-bottom: 32px;
}
.footer-contact a {
  color: var(--text-tertiary);
  transition: color var(--transition-fast);
}
.footer-contact a:hover { color: var(--text-primary); }
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px 24px;
  margin-bottom: 32px;
}
.footer-col { display: flex; flex-direction: column; gap: 12px; }
.footer-link {
  color: var(--text-tertiary);
  text-decoration: none;
  font-size: 0.8rem;
  transition: color var(--transition-fast);
  line-height: 1.2;
}
.footer-link:hover { color: var(--text-primary); text-decoration: underline; }
.footer-bottom {
  margin-top: 32px;
  padding-top: 24px;
  border-top: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-lang select {
  background: var(--input-bg);
  border: 1px solid var(--border);
  color: var(--text-tertiary);
  padding: 8px 32px 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  font-family: inherit;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  transition: all var(--transition-fast);
}
.footer-lang select:hover { background: var(--input-bg-focus); }
.footer-legal { font-size: 0.75rem; color: var(--text-tertiary); }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .trending-card { width: 180px; }
  .trending-poster { width: 180px; height: 252px; }
  .carousel-arrow { display: none; }
}
@media (max-width: 768px) {
  .header-inner { padding: 0 16px; }
  .lang-select { display: none; }
  .section { padding: 56px 0; }
  .container { padding: 0 16px; }
  .hero-form { flex-direction: column; }
  .btn-get-started { justify-content: center; padding: 16px 24px; }
  .hero { padding: 100px 16px 60px; }
  .features-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .trending-card { width: 150px; }
  .trending-poster { width: 150px; height: 210px; }
  .trending-rank { font-size: 4.5rem; left: -6px; bottom: -6px; -webkit-text-stroke: 1.5px rgba(255,255,255,0.3); }
  .faq-question { font-size: 1rem; padding: 20px 4px; }
}
@media (max-width: 480px) {
  .hero-title { font-size: 1.8rem; }
  .hero-subtitle { font-size: 1rem; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 8px 16px; }
}
@media (min-width: 1440px) {
  .container { max-width: 1320px; }
  .trending-card { width: 220px; }
  .trending-poster { width: 220px; height: 308px; }
}

/* ── Reduced Motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}

/* ── Custom Scrollbar for non-mobile ── */
@media (hover: hover) {
  .trending-scroll::-webkit-scrollbar { display: block; height: 4px; }
  .trending-scroll::-webkit-scrollbar-track { background: transparent; }
  .trending-scroll::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.15); border-radius: 4px; }
}
</style>
</head>
