  <div class="hero-poster-3"></div>
  <div class="hero-poster-4"></div>
  <div class="hero-poster-5"></div>
  <div class="hero-poster-6"></div>
  <div class="hero-content">
    <h1 class="hero-title">Unlimited films, series and more</h1>
    <p class="hero-subtitle">Starts at $15.98. Cancel at any time.</p>
    <p class="hero-prompt">Ready to watch? Enter your email to create or restart your membership.</p>
    <form class="hero-form" onsubmit="handleEmailSubmit(event, 'hero')">
      <input
        type="email"
        class="hero-input"
        placeholder="Email address"
        required
        aria-label="Email address"
        autocomplete="email"
      >
      <button type="submit" class="btn-get-started">Get Started <span aria-hidden="true">›</span></button>
    </form>
