<!-- Trending -->
<section class="section" aria-label="Trending now">
  <div class="container">
    <h2 class="section-heading">Trending Now</h2>
    <div class="trending-wrapper">
      <button class="carousel-arrow carousel-arrow-left" aria-label="Scroll left" id="carouselPrev">‹</button>
      <div class="trending-scroll" id="trendingScroll">
        <!-- Generated by JS -->
      </div>
      <button class="carousel-arrow carousel-arrow-right" aria-label="Scroll right" id="carouselNext">›</button>
    </div>
  </div>
</section>

<!-- Features -->
<section class="section" aria-label="More reasons to join">
  <div class="container">
    <h2 class="section-heading">More Reasons to Join</h2>
    <div class="features-grid">
      <div class="feature-card">
        <h3 class="feature-card-title">Enjoy on your TV</h3>
        <p class="feature-card-desc">Watch on smart TVs, PlayStation, Xbox, Chromecast, Apple TV, Blu-ray players and more.</p>
        <div class="feature-card-icon">
          <svg viewBox="0 0 48 48" fill="none" stroke="white" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
            <rect x="5" y="8" width="38" height="28" rx="3"/>
            <polyline points="16,42 32,42"/>
            <line x1="24" y1="36" x2="24" y2="42"/>
          </svg>
        </div>
      </div>
      <div class="feature-card">
        <h3 class="feature-card-title">Download your series to watch offline</h3>
