function validateEmail(val) {
  if (!val.trim()) return false;
  // Accept email or phone (10+ digits)
  if (/^\d{10,}$/.test(val.replace(/[\s\-\(\)]/g, ''))) return true;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
}

